let count = 0;
const btn = document.getElementById('btn');
const out = document.getElementById('out');
btn.addEventListener('click', () => {
  count += 1;
  out.textContent = 'Clicks: ' + count;
  console.log('clicked', count);
});

const form = document.getElementById('f');
const name = document.getElementById('name');
const live = document.getElementById('live');
const result = document.getElementById('result');

name.addEventListener('input', (e) => {
  live.textContent = 'Typing: ' + e.target.value;
});

form.addEventListener('submit', (e) => {
  e.preventDefault(); // stop the page from reloading
  result.textContent = 'Submitted: ' + name.value;
  console.log('submitted', name.value);
});

const log = document.getElementById('log');
document.addEventListener('keydown', (e) => {
  if (e.key === 's') {
    log.textContent = 'Save shortcut!';
    console.log('save', e.key);
  } else if (e.ctrlKey && e.key.toLowerCase() === 'k') {
    e.preventDefault();
    log.textContent = 'Command palette!';
    console.log('ctrl+k');
  }
});

